function validate([dist, speed, hoursBefore]) {
  if (!Array.isArray(dist) || dist.length < 1 || dist.length > 1000) return 'dist needs 1 to 1000 roads.';
  if (dist.some(d => !Number.isInteger(d) || d < 1 || d > 100000)) return 'Each road length is between 1 and 10^5.';
  if (!Number.isInteger(speed) || speed < 1 || speed > 1000000) return 'speed is between 1 and 10^6.';
  if (!Number.isInteger(hoursBefore) || hoursBefore < 1 || hoursBefore > 10000000) return 'hoursBefore is between 1 and 10^7.';
  return null;
}

