function minSkips(dist, speed, hoursBefore) {
  const n = dist.length;
  const dp = new Array(n).fill(Infinity);
  dp[0] = 0;
  for (let i = 0; i < n - 1; i++) {
    for (let skips = i + 1; skips >= 0; skips--) {
      const rested = Math.ceil((dp[skips] + dist[i]) / speed) * speed;
      const skipped = skips > 0 ? dp[skips - 1] + dist[i] : Infinity;
      dp[skips] = Math.min(rested, skipped);
    }
  }
  const limit = hoursBefore * speed;
  for (let skips = 0; skips < n; skips++) {
    if (dp[skips] + dist[n - 1] <= limit) {
      return skips;
    }
  }
  return -1;
}

