function minSkips(dist, speed, hoursBefore) {
  const rests = dist.length - 1;
  let best = -1;
  for (let mask = 0; mask < (1 << rests); mask++) {
    // Track time as whole hours plus a remainder in units of 1/speed hours.
    let hours = 0;
    let rem = 0;
    for (let i = 0; i < dist.length; i++) {
      rem += dist[i];
      hours += Math.floor(rem / speed);
      rem %= speed;
      if (i < rests && !(mask & (1 << i)) && rem > 0) { hours++; rem = 0; }
    }
    const onTime = hours < hoursBefore || (hours === hoursBefore && rem === 0);
    if (!onTime) continue;
    let bits = 0;
    for (let m = mask; m; m >>= 1) bits += m & 1;
    if (best === -1 || bits < best) best = bits;
  }
  return best;
}

