function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  const large = size === 'large';
  const n = large ? (rand() < 0.7 ? 1000 : int(500, 1000)) : int(1, 8);
  let speed;
  let distMax;
  if (large) {
    const kind = rand();
    if (kind < 0.3) { speed = int(1, 10); distMax = int(1, 1000); }
    else if (kind < 0.7) { speed = int(100, 1000000); distMax = 100000; }
    else { speed = 1000000; distMax = int(1, 100000); }
  } else {
    speed = int(1, 8);
    distMax = rand() < 0.5 ? 10 : 30;
  }
  const dist = Array.from({ length: n }, () => int(1, distMax));
  let sum = 0;
  let plain = 0;
  for (let i = 0; i < n; i++) {
    sum += dist[i];
    plain += dist[i];
    if (i < n - 1) plain = Math.ceil(plain / speed) * speed;
  }
  const fewest = Math.ceil(sum / speed);
  const most = Math.ceil(plain / speed);
  const roll = rand();
  let hoursBefore = roll < 0.1 ? fewest - 1 : roll < 0.2 ? most + int(0, 3) : int(fewest, most);
  hoursBefore = Math.min(Math.max(hoursBefore, 1), 10000000);
  return [dist, speed, hoursBefore];
}
